import fs from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test("documents from another tenant are invisible", { tag: "@DOC-07" }, async ({ apiAs }) => {
  // Arrange: a Northwind member has a vendor in draft
  const member = await apiAs("member");
  const ownVendor = await member.post("/api/vendors", {
    data: { name: uniqueName("Northwind Draft"), category: "services", contact_email: "ops@northwind-supply.com" },
  });
  expect(ownVendor.status(), await ownVendor.text()).toBe(201);
  expect(((await ownVendor.json()) as { status: string }).status).toBe("draft");

  // Arrange: a document exists in tenant Globex Procurement
  const globex = await apiAs("otherTenant");
  const otherVendor = await globex.post("/api/vendors", {
    data: { name: uniqueName("Globex Vendor"), category: "services", contact_email: "ops@globex-supply.com" },
  });
  expect(otherVendor.status(), await otherVendor.text()).toBe(201);
  const otherVendorId = ((await otherVendor.json()) as { id: string }).id;

  const upload = await globex.post(`/api/vendors/${otherVendorId}/documents`, {
    multipart: {
      kind: "insurance_certificate",
      file: {
        name: "insurance_certificate.txt",
        mimeType: "text/plain",
        buffer: fs.readFileSync(sample("insurance_certificate.txt")),
      },
    },
  });
  expect(upload.status(), await upload.text()).toBe(201);
  const documentId = ((await upload.json()) as { id: string }).id;

  // Act: the Northwind member requests the Globex document by id
  const response = await member.get(`/api/documents/${documentId}`);

  // Assert
  expect(response.status(), await response.text()).toBe(404);
  const body = (await response.json()) as { error: { code: string } };
  expect(body.error.code, await response.text()).toBe("document_not_found");
});
